from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class SyncParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.is_mo_ecpri:
            self.set_parameter('profileType', 'RU')
            self.set_targetDNList()

        else:
            self.set_actEcpriMasterClock(execution_config)
            self.set_btsSyncMode()
            if not self.enb_ent_config['has_freq_sync']:
                self.set_parameter('manualFrameTimingAdjustment', 0)

    def set_targetDNList(self):
        target_dn = f'MRBTS-{self.enb_ent_config["id"]}/EQM-1/APEQM-1/RMOD-'
        target_dn_list = tuple(target_dn + radio_num for radio_num in sorted(self.enb_ent_config['radios'], key=int))
        self.set_parameter('targetDNList', target_dn_list)  # list of params without name

    def set_actEcpriMasterClock(self, execution_config):
        if execution_config['hardware_platform'] == 'CUS2' and execution_config['duplex_mode'] != 'FDD':
            self.set_parameter('actEcpriMasterClock', 'true')
        else:
            self.set_parameter('actEcpriMasterClock', 'false')

    def set_btsSyncMode(self):
        if self.enb_ent_config['has_freq_sync']:
            self.set_parameter('btsSyncMode', 'FreqSync')
        else:
            self.set_parameter('btsSyncMode', 'PhaseSync')
